class Example {
    String format(String s) {
        String redundant = "" + s + " some other text"; // violation
        String correct = s + " some other text";
        return correct;
    }
}

class Example {
    String a = "a" + 1 + ""; // violation
    String b = "a" + (1 + ""); // violation
    String c = "a" + "" + 1; // violation
}

class Example {
    String a = "" + "a"; // violation
    String b = "b" + ""; // violation
    String c = "" + ""; // violation
    static final String TEXT = "text";
    String d = TEXT + ""; // violation
}

class Example {
    String format(Object value) {
        String a = (value + " suffix") + ""; // violation
        String b = "" + ("prefix" + value); // violation
        return a + b;
    }
}

class Example {
    String format(String value) {
        String a = value + "";
        String b = "" + value;
        String c = ((value)) + "";
        String d = (String) null + "";
        return a + b + c + d;
    }
}

class Example {
    String format(String s, String t) {
        String a = s + "" + 1; // violation
        String b = 1 + (s + ""); // violation
        String c = (s + "") + t; // violation
        String d = s + ("" + t); // violation
        return a + b + c + d;
    }
}

class Example {
    String format(int number) {
        String a = "" + number + ":"; // violation
        String b = ":" + (number + ""); // violation
        String c = number + "" + ":"; // violation
        return a + b + c;
    }
}

class Example {
    String format(boolean flag, char letter, long count, float ratio, double value) {
        String a = "" + flag + ":"; // violation
        String b = ":" + (letter + ""); // violation
        String c = count + "" + ":"; // violation
        String d = "" + ratio + ":"; // violation
        String e = ":" + (value + ""); // violation
        return a + b + c + d + e;
    }
}

class Example {
    String a = "" + null + " suffix"; // violation
    String b = "prefix" + (null + ""); // violation
}

class Example {
    String format(int n, int m) {
        String a = "" + n + m;
        String b = "" + n + m + " suffix";
        String c = 1 + ("" + 2);
        String d = "prefix" + (1 + "" + 2);
        String e = (n + "" + m) + " suffix";
        String f = "" + 1.0 + 2.0 + " suffix";
        return a + b + c + d + e + f;
    }
}

class Example {
    String format(int n, int m) {
        String a = "" + (n + m) + " suffix"; // violation
        String b = "" + n + m + " suffix";
        return a + b;
    }
}

