class Example {
    String a = 1 + "";
    String b = null + "";
    String c = 1 + "" + 1;
    String d = "" + true;
    String e = 'a' + "";
    String f = "" + 1.5;
    String g = "" + 1L;
}

class Example {
    String format(Object value) {
        String a = value + "";
        String b = "" + value;
        String c = "" + value + changeValueAndGetSuffix(value);
        String d = "prefix" + (value + "");
        return a + b + c + d;
    }
    String changeValueAndGetSuffix(Object value) {
        return "suffix";
    }
}

class Example {
    String format(char[] chars, int[] numbers, Integer number) {
        String a = chars + "";
        String b = "" + numbers;
        String c = "" + chars + " suffix";
        String d = "prefix" + (number + "");
        return a + b + c + d;
    }
}

class Example {
    String format() {
        final Object object = "text";
        final CharSequence sequence = "text";
        String a = object + "";
        String b = "" + sequence;
        String c = (true ? "text" : 1) + "";
        String d = "" + object + " suffix";
        return a + b + c + d;
    }
}

class Example {
    String format(MissingType unknown) {
        String a = "" + unknown;
        String b = "" + unknown + " suffix";
        String c = "prefix" + (unknown + "");
        String d = "" + unknown.getValue() + " suffix";
        return a + b + c + d;
    }
}

class Example {
    static final String EMPTY = "";
    String format(String s) {
        String a = "a" + "b";
        String b = EMPTY + s + " suffix";
        String c = s + " ";
        s += "";
        return a + b + c + s;
    }
}

class Example {
    String format(int number) {
        String a = "prefix" + ((number + (""))); // violation
        String b = (("")) + ((number)) + " suffix"; // violation
        String c = 1 + (("" + 2));
        return a + b + c;
    }
}

class Example {
    String format(String s) {
        return "" // violation
            + wrap(s + "" + " inner") // violation
            + " outer";
    }
    String wrap(String s) {
        return s;
    }
}

class Example {
    String format() {
        String a = "" + getText() + " suffix"; // violation
        String b = "prefix" + (getNumber() + ""); // violation
        String c = getText() + "";
        return a + b + c;
    }
    String getText() { return null; }
    int getNumber() { return 1; }
}

